#include <bits/stdc++.h>
using namespace std;


int main() {
	int tt; cin >> tt;
	while(tt--){
	    int n; cin >> n; //upto 2000
	    int k; cin >> k; 
	    string s; cin >> s; 
        //cout << s;
	    vector<char> bag1;
	    vector<char> bag2;
	    //cout << bag1.size() << bag2.size();
	    int lowest_g = n;
	    bool done = false;
	    bool flag1 = true;
	    int w = 0;
	    for(int i = 0; i < n; i++){
	        if(s[i] == 'G'){
	            if(bag1.size() <= k)bag1.push_back(s[i]);
	            else{
	                if(!flag1){w += 1;}
	                if(flag1){
	                    //cout << "flag1 happened";
	                    flag1 = false;
	                    lowest_g = (int)bag2.size();
	                }
	                bag2.push_back(s[i]);
	            }
	        }else{
	            if(!flag1)w += 2;
	            bag2.push_back(s[i]);
	        }
	        
	        if(((int)bag1.size()-1) > k){
	            //cout << bag1.size() << ' '; 
	            cout << "1NO\n"; done = true;
	            break;
	        }
	        if(w > k){cout << "NO\n"; done = true; break;}
	    }
	    if(done == false)cout << "YES\n";
	}
}
